import{_ as o,C as t,o as s,c as i,E as n,a2 as c}from"./chunks/framework.Cm6XCzck.js";const v=JSON.parse('{"title":"Both Instructions Were Saved. Why Did Recovery Reverse Their Meaning?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Both Instructions Were Saved. Why Did Recovery Reverse Their Meaning?","date":"2026-09-05","published_date":"2026-09-06","column":"open-source-engineering","category":"daily","article_type":"research-methodology","edition":"research-center","summary":"Order is part of context. With no input missing, replay can still reverse a decision when persistence order differs from acceptance order. Inspired by a Codex change, seven controlled scenarios separate receipt, acceptance, storage, recovery, and authority—not establish a real CodeFlowMu conversation-ordering defect.","cover":"/assets/read-effects-order-20260905/assets/acceptance-order-cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Controlled replay study complete; CodeFlowMu Host ordering defect not established","pageClass":"read-effects-article"},"headers":[],"relativePath":"en/engineering/2026-09-05-acceptance-order-replay.md","filePath":"en/engineering/2026-09-05-acceptance-order-replay.md","lastUpdated":1788665923000}'),d={name:"en/engineering/2026-09-05-acceptance-order-replay.md"};function l(p,e,h,u,m,g){const r=t("ArticleCover"),a=t("ArticleTableScroll");return s(),i("div",null,[n(r,{image:"/assets/read-effects-order-20260905/assets/acceptance-order-cover-v1.png",kicker:"Open-source engineering · Controlled experiment",title:"Both Instructions Were Saved. Why Did Recovery Reverse Their Meaning?",summary:"Order is part of context. With no input missing, replay can still reverse a decision when persistence order differs from acceptance order. Inspired by a Codex change, seven controlled scenarios separate receipt, acceptance, storage, recovery, and authority—not establish a real CodeFlowMu conversation-ordering defect.",version:"2026-09-05",languageHref:"/zh/engineering/2026-09-05-acceptance-order-replay",languageLabel:"中文"}),n(a,{language:"en"}),e[0]||(e[0]=c(`<h1 id="both-instructions-were-saved-why-did-recovery-reverse-their-meaning" tabindex="-1">Both Instructions Were Saved. Why Did Recovery Reverse Their Meaning? <a class="header-anchor" href="#both-instructions-were-saved-why-did-recovery-reverse-their-meaning" aria-label="Permalink to &quot;Both Instructions Were Saved. Why Did Recovery Reverse Their Meaning?&quot;">​</a></h1><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/assets/acceptance-order-cover-v1.png" target="_blank" rel="noreferrer">View original cover</a></p><p>Suppose you tell an agent—a system that can use tools to carry out tasks—“allow execution,” then change your mind and say “revoke permission.”</p><p>If the system accepts both instructions in that order, the final meaning is clear: execution is no longer allowed.</p><p>Now suppose both messages are saved. Nothing is missing. But asynchronous persistence finishes the second write before the first. After a restart, a recovery program that trusts file order encounters “revoke” followed by “allow.”</p><p>The words are intact, yet their meaning can reverse.</p><p>The problem is not suddenly poor language comprehension. It is treating <strong>which record finished writing first as which instruction was accepted first</strong>. For order-sensitive input, saving all the content does not necessarily preserve the original context.</p><p><strong>Order itself is part of context.</strong></p><p>A recent change in Codex, OpenAI&#39;s coding-agent project, addresses this distinction. It prompted us to run a minimal experiment without a model: change the ordering basis used during recovery and observe whether the decision changes. Then we examined how that question relates to CodeFlowMu&#39;s existing execution safeguards.</p><h2 id="_1-why-acceptance-and-persistence-are-different-events" tabindex="-1">1. Why acceptance and persistence are different events <a class="header-anchor" href="#_1-why-acceptance-and-persistence-are-different-events" aria-label="Permalink to &quot;1. Why acceptance and persistence are different events&quot;">​</a></h2><p>Consider a café order. A customer orders a coffee and then cancels it; the server acknowledges both requests. Separate backend queues print the cancellation slip first and the order slip second.</p><p>Someone reviewing the paper stack might conclude that the coffee should be made. No slip is missing. <strong>Print-completion order simply differs from acknowledgment order.</strong></p><p>Agent input has similar handoffs: arrival, acceptance, and persistence can occur close together without being the same event.</p><p>Here, the Host means the system that manages agent conversations, accepts inputs, and assembles context. Acceptance order is the logical order in which that responsible system accepts input—not merely network arrival or storage completion.</p><p><a href="https://github.com/openai/codex/pull/42770" target="_blank" rel="noreferrer">Codex #42770</a>, merged September 4, 2026, describes queued prompts and human-input answers being persisted in an order different from Host acceptance. Using recording order can reorder retained thread context or apply the wrong rollback boundary: which inputs remain when returning to an earlier point.</p><p>With retained thread context enabled, the change preserves acceptance sequences for relevant inputs and uses them for replay and boundary handling. Legacy records without acceptance metadata retain recording-order compatibility.</p><p>The value is not just an extra number. Recovery gains a basis for distinguishing “accepted first” from “saved first.” The sequence is still not an authorization credential: it establishes order, not who may approve an action.</p><h2 id="_2-isolate-ordering-instead-of-testing-model-comprehension" tabindex="-1">2. Isolate ordering instead of testing model comprehension <a class="header-anchor" href="#_2-isolate-ordering-instead-of-testing-model-comprehension" aria-label="Permalink to &quot;2. Isolate ordering instead of testing model comprehension&quot;">​</a></h2><p>We did not simulate a large language model. We wrote a transparent state reducer: a small program that processes operations in sequence and updates state. It recognizes only:</p><ul><li><code>allow</code>: set the experimental state to allowed;</li><li><code>revoke</code>: set it to denied.</li></ul><p>Both inputs have <strong>equal authority within one experimental scope</strong>. This isolates ordering; it does not model an administrator&#39;s authority relative to an ordinary user&#39;s, or implement a real business authorization service.</p><p>Each scenario saves two artifacts: input acceptance status with assigned sequences, and a line-oriented log written in a specified order, with a storage sync requested after each entry. A separate Node.js process reads the log and computes the result using recording order and acceptance order.</p><p>The central comparison is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accepted: 1 allow → 2 revoke</span></span>
<span class="line"><span>Persisted: 2 revoke → 1 allow</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Replay by recording order: allow</span></span>
<span class="line"><span>Replay by acceptance order: deny</span></span></code></pre></div><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/assets/acceptance-replay-inline-v1.png" target="_blank" rel="noreferrer"><img src="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/assets/acceptance-replay-inline-v1.png" alt="O1 illustration: acceptance-order replay yields deny; recording-order replay yields allow"></a></p><p><em>Figure 1. Two replay interpretations of O1, not two independent grants of authority. Both rows use the same accepted records, whose identity numbers stay attached to the original input. The experimental inputs have equal authority; this does not establish a real conversation exceeding authority. Source: mechanism illustration of this article’s controlled experiment, not a raw observation screenshot. Click for the full-resolution image.</em></p><p>Both readers use the same records without changing their contents. The decision flips because they trust different ordering evidence.</p><p>The inversion was <strong>deliberately imposed</strong>, not observed as a naturally occurring production incident. The experiment asks whether this separation can change a result—not how often it occurs.</p><p>Likewise, fresh-process replay establishes that another process can read and replay this experimental log. It is not a real agent-session crash-recovery test.</p><h2 id="_3-seven-controls-identify-when-inversion-matters" tabindex="-1">3. Seven controls identify when inversion matters <a class="header-anchor" href="#_3-seven-controls-identify-when-inversion-matters" aria-label="Permalink to &quot;3. Seven controls identify when inversion matters&quot;">​</a></h2><p>Seven scenarios ran twice, yielding 14 fresh-process replay observations. Results matched across rounds.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Inputs and disturbance</th><th>Recording-order replay</th><th>Acceptance-order replay</th></tr></thead><tbody><tr><td>O0</td><td>allow → revoke, normal persistence</td><td>deny</td><td>deny</td></tr><tr><td>O1</td><td>allow → revoke, inverted persistence</td><td>allow</td><td>deny</td></tr><tr><td>O2</td><td>revoke → allow, inverted persistence</td><td>deny</td><td>allow</td></tr><tr><td>O3</td><td>revoke → revoke, inverted persistence</td><td>deny</td><td>deny</td></tr><tr><td>O4</td><td>revoke followed by an unaccepted allow</td><td>deny</td><td>deny</td></tr><tr><td>O5</td><td>Inversion with one missing acceptance sequence</td><td>allow</td><td>unknown</td></tr><tr><td>O6</td><td>Inversion with duplicate acceptance sequences</td><td>allow</td><td>unknown</td></tr></tbody></table><p>O1 reproduces the opening example. O2 shows that the effect can go the other way: a later permission is misinterpreted as already revoked. The issue is not exclusively excess permission; it can also leave a decision incorrectly denied.</p><p>O3 is an essential negative control. Reordering two revocations leaves the result unchanged. <strong>Out-of-order records do not necessarily produce a wrong decision; the operations must also be order-sensitive.</strong></p><p>O4 separates arrival from acceptance. The later allow appears in the log but was not accepted. Both readers filter it out before processing; later placement alone gives it no effect on state.</p><p>O5 and O6 test the ordering evidence itself. Missing or duplicate sequences cannot establish a unique reliable acceptance order, so our acceptance-based reader returns unknown rather than manufacturing history from file position.</p><p>Unknown expresses insufficient evidence, not a universal real-world handling policy. In particular, <strong>our reader returns unknown for invalid sequences; Codex retains recording-order compatibility for legacy records lacking acceptance metadata. These address different cases with different rules.</strong></p><h2 id="_4-correct-order-must-not-import-the-future-into-the-past" tabindex="-1">4. Correct order must not import the future into the past <a class="header-anchor" href="#_4-correct-order-must-not-import-the-future-into-the-past" aria-label="Permalink to &quot;4. Correct order must not import the future into the past&quot;">​</a></h2><p>There is another independent question: which point in the conversation are we restoring?</p><p>If the system accepted allow followed by revoke, a reconstruction of what it knew immediately after the first input may contain only allow. The revocation happened later; it must not affect that earlier judgment.</p><p>The same experiment therefore applies a cutoff: use only records whose acceptance sequence is at most 1. In O0 and O1, regardless of final file order, that cutoff yields only the first allow, without importing the later revoke.</p><p><strong>Sorting establishes which input precedes another. A cutoff establishes which inputs may enter the judgment at the selected boundary.</strong></p><p>Our cutoff is defined by acceptance sequence. It is not a complete validation of wall-clock timestamps, evidence visibility, or access control in arbitrary systems. The narrower lesson is that ordering and recovery boundaries each need explicit treatment.</p><h2 id="_5-codeflowmu-s-existing-command-safeguards-answer-a-different-question" tabindex="-1">5. CodeFlowMu&#39;s existing command safeguards answer a different question <a class="header-anchor" href="#_5-codeflowmu-s-existing-command-safeguards-answer-a-different-question" aria-label="Permalink to &quot;5. CodeFlowMu&#39;s existing command safeguards answer a different question&quot;">​</a></h2><p>CodeFlowMu is a local multi-agent collaboration system we are developing. Its FCoP file-based collaboration protocol maintains tasks, reports, and role responsibilities; its Runtime performs explicit technical actions. Formal task decisions do not simply follow the final sentence in a chat log.</p><p>This study fixed product code at commit <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>. Its common task-command checking entry point, <code>TaskCommandKernel</code>, checks task and thread identity, task revision, execution round, role or scope authorization, and idempotency receipts—records used to recognize repeated commands and reuse completed results.</p><p>The related command and role suites contained 31 tests, run twice. Each round had 31 passes, zero failures, and zero skips. That is not 62 distinct tests. The relevant evidence is the specific boundary each control verifies:</p><table tabindex="0"><thead><tr><th>Existing check</th><th>Verified boundary</th></tr></thead><tbody><tr><td>Stale task revision</td><td><code>stale_task_revision</code>; zero calls to the underlying action</td></tr><tr><td>Stale execution round</td><td>An old-round request cannot thereby change the current task</td></tr><tr><td>Same idempotency key, different semantic content</td><td>Conflict rejected rather than treated as the original command</td></tr><tr><td>Replay of a completed command receipt</td><td>Result reused without executing the action again</td></tr></tbody></table><p>Acceptance order asks which instruction came first. A task-revision check asks whether a command still addresses the current task state. Neither substitutes for the other.</p><p>An accurately restored permission concerning revision 5 does not automatically authorize an operation on the current revision 6. Conversely, rejecting revision 5 correctly does not establish that conversation persistence and recovery preserve input order.</p><p>The Codex <code>steer()</code> adapter also passes an expected conversation-turn identity and an optional user-message identifier. Their presence alone does not prove that acceptance order survives storage, compaction, and recovery.</p><p>A conversation turn and a formal task execution round are distinct concepts, too. One organizes interaction; the other constrains task execution. Similar terminology does not make them interchangeable.</p><p><strong>Our mechanism experiment does not establish a real CodeFlowMu conversation-ordering defect. Passing existing command tests does not establish correct conversation-context recovery either.</strong></p><h2 id="_6-investigate-three-handoffs-before-building-another-component" tabindex="-1">6. Investigate three handoffs before building another component <a class="header-anchor" href="#_6-investigate-three-handoffs-before-building-another-component" aria-label="Permalink to &quot;6. Investigate three handoffs before building another component&quot;">​</a></h2><p>These distinctions determine how an external change becomes our own engineering research rather than automatically becoming an implementation task.</p><p><strong>First, who acknowledges acceptance, and when?</strong> Request arrival, successful queuing, acceptance by the target conversation, and use in the current turn can be different events. The context-owning system should identify the relevant event instead of reconstructing it later from file-write time.</p><p><strong>Second, how does that fact survive persistence and recovery?</strong> What is the sequence&#39;s scope? How is uniqueness maintained? What happens when metadata is missing or duplicated? Does it survive compaction? Which boundary does rollback use? How are legacy records handled? These require implementation-specific evidence. Renumbering today&#39;s file order cannot establish historical acceptance order.</p><p><strong>Third, who verifies present execution eligibility?</strong> Correct ordering reconstructs history. Current role, task revision, execution round, authorization validity, and whether an action has already taken effect still require their respective execution rules.</p><p>Meeting minutes can faithfully establish who spoke first without proving who had authority to approve a payment. The same distinction applies here: <strong>acceptance order is not authorization, and permission in the past is not automatically permission now.</strong></p><p>These handoffs become more valuable as agents run longer. Queuing, human answers, compaction, restarts, and rollback make context a history with ordering and boundaries—not just a list of strings. Greater model intelligence does not automatically preserve those relationships.</p><p>We therefore did not propose immediately adding another acceptance-sequence module to CodeFlowMu. The next step is to examine the actual input–acceptance–storage–compaction–recovery chain, establish what the Host already provides and what belongs locally, and only then decide whether a product gap requires development.</p><h2 id="_7-complete-records-do-not-automatically-preserve-complete-meaning" tabindex="-1">7. Complete records do not automatically preserve complete meaning <a class="header-anchor" href="#_7-complete-records-do-not-automatically-preserve-complete-meaning" aria-label="Permalink to &quot;7. Complete records do not automatically preserve complete meaning&quot;">​</a></h2><p>This study establishes that substituting persistence order for acceptance order can change recovery results in a fixed, order-sensitive minimal model. Reverse-direction flips, identical operations, unaccepted input, invalid sequences, and cutoffs define the limits of that finding.</p><p>It does not measure natural race frequency, demonstrate a real agent exceeding authority, or test cross-user privilege conflicts, cancellation of in-flight effects, or the complete context-compaction pipeline. We did not run Codex&#39;s Rust tests. An existing CodeFlowMu receipt test named for process restart reconstructs objects with receipt dependencies; it cannot be presented as an additional real Host crash-recovery test.</p><p>This research did not grant new product-development authorization.</p><p>Why can both instructions be saved while their meaning reverses? For order-sensitive context, preserving content need not preserve how it originally formed a history.</p><p><strong>Reliable recovery must preserve the order and boundaries needed to interpret records, not merely retrieve them. Restoring past meaning does not grant present execution authority.</strong></p><h2 id="evidence-and-checking" tabindex="-1">Evidence and checking <a class="header-anchor" href="#evidence-and-checking" aria-label="Permalink to &quot;Evidence and checking&quot;">​</a></h2><p>The companion <a href="/joinwell52/en/research/evidence/2026-09-05-read-effects-acceptance-order">evidence guide</a> includes both de-identified replay rounds, a standalone ordering probe, formal-command test summaries, and fixed-source hashes.</p><p>The evidence checker validates exported-observation consistency and file integrity. It does not rerun product code or establish detection accuracy, production reliability, or independent acceptance. This editorial revision adds no experiments; all figures still refer to the September 5, 2026 fixed baseline.</p>`,70))])}const y=o(d,[["render",l]]);export{v as __pageData,y as default};
